-- ---- triggers -----------------------------------------------------------

CREATE TRIGGER trg_dataset_relationship_same_site_insert
BEFORE INSERT ON dataset_relationship
FOR EACH ROW
WHEN (SELECT site_profile_id FROM dataset_definition
      WHERE dataset_definition_id = NEW.parent_dataset_id LIMIT 1) <> NEW.site_profile_id
  OR (SELECT site_profile_id FROM dataset_definition
      WHERE dataset_definition_id = NEW.child_dataset_id LIMIT 1) <> NEW.site_profile_id
BEGIN
    SELECT RAISE(ABORT, 'relationship datasets must belong to the same site profile');
END;

CREATE TRIGGER trg_dataset_relationship_same_site_update
BEFORE UPDATE OF site_profile_id, parent_dataset_id, child_dataset_id
ON dataset_relationship
FOR EACH ROW
WHEN (SELECT site_profile_id FROM dataset_definition
      WHERE dataset_definition_id = NEW.parent_dataset_id LIMIT 1) <> NEW.site_profile_id
  OR (SELECT site_profile_id FROM dataset_definition
      WHERE dataset_definition_id = NEW.child_dataset_id LIMIT 1) <> NEW.site_profile_id
BEGIN
    SELECT RAISE(ABORT, 'relationship datasets must belong to the same site profile');
END;

CREATE TRIGGER trg_generic_ingestion_append_only_delete
BEFORE DELETE ON generic_ingestion
BEGIN
    SELECT RAISE(ABORT, 'generic ingestions are append-only');
END;

CREATE TRIGGER trg_generic_ingestion_append_only_update
BEFORE UPDATE ON generic_ingestion
BEGIN
    SELECT RAISE(ABORT, 'generic ingestions are append-only');
END;

CREATE TRIGGER trg_generic_ingestion_matches_insert
BEFORE INSERT ON generic_ingestion
FOR EACH ROW
WHEN NEW.dataset_definition_id <>
     (SELECT dataset_definition_id FROM dataset_schema_version
      WHERE schema_version_id = NEW.schema_version_id LIMIT 1)
BEGIN
    SELECT RAISE(ABORT, 'generic ingestion schema must belong to its dataset');
END;

CREATE TRIGGER trg_generic_page_snapshot_immutable_delete
BEFORE DELETE ON generic_page_snapshot
BEGIN
    SELECT RAISE(ABORT, 'saved HTML snapshots are immutable');
END;

CREATE TRIGGER trg_generic_page_snapshot_immutable_update
BEFORE UPDATE ON generic_page_snapshot
BEGIN
    SELECT RAISE(ABORT, 'saved HTML snapshots are immutable');
END;

CREATE TRIGGER trg_generic_record_revision_append_only_delete
BEFORE DELETE ON generic_record_revision
BEGIN
    SELECT RAISE(ABORT, 'generic record revisions are append-only');
END;

CREATE TRIGGER trg_generic_record_revision_append_only_update
BEFORE UPDATE ON generic_record_revision
BEGIN
    SELECT RAISE(ABORT, 'generic record revisions are append-only');
END;

CREATE TRIGGER trg_generic_record_revision_matches_insert
BEFORE INSERT ON generic_record_revision
FOR EACH ROW
WHEN (SELECT dataset_definition_id FROM dataset_schema_version
      WHERE schema_version_id = NEW.schema_version_id LIMIT 1) <>
     (SELECT dataset_definition_id FROM generic_record
      WHERE generic_record_id = NEW.generic_record_id LIMIT 1)
BEGIN
    SELECT RAISE(ABORT, 'generic record revision schema must belong to its dataset');
END;

CREATE TRIGGER trg_generic_record_schema_matches_insert
BEFORE INSERT ON generic_record
FOR EACH ROW
WHEN NEW.dataset_definition_id <>
     (SELECT dataset_definition_id FROM dataset_schema_version
      WHERE schema_version_id = NEW.schema_version_id LIMIT 1)
BEGIN
    SELECT RAISE(ABORT, 'generic record schema must belong to its dataset');
END;

CREATE TRIGGER trg_generic_record_schema_matches_update
BEFORE UPDATE OF dataset_definition_id, schema_version_id ON generic_record
FOR EACH ROW
WHEN NEW.dataset_definition_id <>
     (SELECT dataset_definition_id FROM dataset_schema_version
      WHERE schema_version_id = NEW.schema_version_id LIMIT 1)
BEGIN
    SELECT RAISE(ABORT, 'generic record schema must belong to its dataset');
END;

CREATE TRIGGER trg_offer_unit_needs_a_witness_insert
BEFORE INSERT ON source_offer
WHEN NEW.selling_unit_id IS NOT NULL
 AND (NEW.unit_basis_provenance IS NULL OR NEW.unit_basis_provenance = ''
   OR NEW.unit_basis_witness IS NULL OR NEW.unit_basis_witness = '')
BEGIN
  SELECT RAISE(ABORT, 'a selling unit must carry its provenance and its witness');
END;

CREATE TRIGGER trg_offer_unit_needs_a_witness_update
BEFORE UPDATE OF selling_unit_id, unit_basis_provenance, unit_basis_witness ON source_offer
WHEN NEW.selling_unit_id IS NOT NULL
 AND (NEW.unit_basis_provenance IS NULL OR NEW.unit_basis_provenance = ''
   OR NEW.unit_basis_witness IS NULL OR NEW.unit_basis_witness = '')
BEGIN
  SELECT RAISE(ABORT, 'a selling unit must carry its provenance and its witness');
END;

CREATE TRIGGER trg_price_obs_no_delete
BEFORE DELETE ON price_observation
BEGIN
    SELECT RAISE(ABORT, 'price_observation is append-only (ENGINEERING.md A7)');
END;

CREATE TRIGGER trg_price_obs_no_update
BEFORE UPDATE ON price_observation
BEGIN
    SELECT RAISE(ABORT, 'price_observation is append-only (ENGINEERING.md A7)');
END;

CREATE TRIGGER trg_relationship_field_pair_matches_insert
BEFORE INSERT ON relationship_field_pair
FOR EACH ROW
WHEN (SELECT dataset_definition_id FROM field_definition
      WHERE field_definition_id = NEW.parent_field_id LIMIT 1) <>
     (SELECT parent_dataset_id FROM dataset_relationship
      WHERE dataset_relationship_id = NEW.dataset_relationship_id LIMIT 1)
  OR (SELECT dataset_definition_id FROM field_definition
      WHERE field_definition_id = NEW.child_field_id LIMIT 1) <>
     (SELECT child_dataset_id FROM dataset_relationship
      WHERE dataset_relationship_id = NEW.dataset_relationship_id LIMIT 1)
BEGIN
    SELECT RAISE(ABORT, 'relationship fields must belong to their mapped datasets');
END;

CREATE TRIGGER trg_relationship_field_pair_matches_update
BEFORE UPDATE OF dataset_relationship_id, parent_field_id, child_field_id
ON relationship_field_pair
FOR EACH ROW
WHEN (SELECT dataset_definition_id FROM field_definition
      WHERE field_definition_id = NEW.parent_field_id LIMIT 1) <>
     (SELECT parent_dataset_id FROM dataset_relationship
      WHERE dataset_relationship_id = NEW.dataset_relationship_id LIMIT 1)
  OR (SELECT dataset_definition_id FROM field_definition
      WHERE field_definition_id = NEW.child_field_id LIMIT 1) <>
     (SELECT child_dataset_id FROM dataset_relationship
      WHERE dataset_relationship_id = NEW.dataset_relationship_id LIMIT 1)
BEGIN
    SELECT RAISE(ABORT, 'relationship fields must belong to their mapped datasets');
END;

CREATE TRIGGER trg_schema_version_field_matches_insert
BEFORE INSERT ON schema_version_field
FOR EACH ROW
WHEN (SELECT dataset_definition_id FROM field_definition
      WHERE field_definition_id = NEW.field_definition_id LIMIT 1) <>
     (SELECT dataset_definition_id FROM dataset_schema_version
      WHERE schema_version_id = NEW.schema_version_id LIMIT 1)
BEGIN
    SELECT RAISE(ABORT, 'schema fields must belong to the schema dataset');
END;

CREATE TRIGGER trg_schema_version_field_matches_update
BEFORE UPDATE OF schema_version_id, field_definition_id ON schema_version_field
FOR EACH ROW
WHEN (SELECT dataset_definition_id FROM field_definition
      WHERE field_definition_id = NEW.field_definition_id LIMIT 1) <>
     (SELECT dataset_definition_id FROM dataset_schema_version
      WHERE schema_version_id = NEW.schema_version_id LIMIT 1)
BEGIN
    SELECT RAISE(ABORT, 'schema fields must belong to the schema dataset');
END;

